import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
answers = []


def add(index, paragraphs, reason, notes, removed=None, checks=None):
    source = sources[index]
    result = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    result.update(
        proposed_xml='\n'.join('<p>' + paragraph + '</p>' for paragraph in paragraphs),
        reason=reason,
        review_notes=notes,
        status='rewrite_draft',
    )
    if removed:
        result.update(change_type='normative_reduction',
                      reform_policy_id='editorial_direction_2026_10_19',
                      removed_provisions=removed)
    if checks:
        result['reference_checks'] = checks
    answers.append(result)


